define({"topics":[{"title":"Electrical Safety","shortdesc":"<p class=\"shortdesc\">You must follow all recommended safety procedures when servicing and working near energy sources.<\/p>","href":"r_ElectricalSafety_85.html","attributes":{"data-id":"id_2001693"},"menu":{"hasChildren":false},"tocID":"id_2001693-d46e298473","topics":[]},{"title":"Shutting down the host computer","shortdesc":"<p class=\"shortdesc\">Shutting down the host computer shuts down the system safely and turns off the power to the host computer.<\/p>","href":"t_ShuttingDownHostComputer_85.html","attributes":{"data-id":"id_2001469"},"menu":{"hasChildren":false},"tocID":"id_2001469-d46e298577","topics":[]},{"title":"Applying LOTO - ISC","shortdesc":"<p class=\"shortdesc\">Apply LOTO to both the gradient and system Power Distribution Unit (PDU) breakers on the MDP when servicing either of these items in the ISC. Apply LOTO to make sure of a safe environment when working on these parts.<\/p>","href":"t_Applying-LOTO-ISC_75.html","attributes":{"data-id":"id_2001781"},"menu":{"hasChildren":false},"tocID":"id_2001781-d46e298681","topics":[]},{"title":"Removing the magnet service access trim","shortdesc":"<p class=\"shortdesc\">Removes the service access trim. The trim panel covers the screws securing the front and rear service access panels.<\/p>","href":"t_RemovingTheServiceAccessTrim_28.html","attributes":{"data-id":"id_2002821"},"menu":{"hasChildren":false},"tocID":"id_2002821-d46e298787","topics":[]},{"title":"Removing the magnet front service access panel","shortdesc":"<p class=\"shortdesc\">Removes the front service access panel from the magnet to allow access to components mounted on the left-hand side of the magnet.<\/p>","href":"t_RemovingTheFrontServiceAccessPanel_26.html","attributes":{"data-id":"id_2002823"},"menu":{"hasChildren":false},"tocID":"id_2002823-d46e298891","topics":[]},{"title":"Removing the magnet rear service access panel","shortdesc":"<p class=\"shortdesc\">Removes the rear service access panel from the magnet to allow access to components mounted on the left-hand side of the magnet.<\/p>","href":"t_RemovingTheRearServiceAccessPanel_24.html","attributes":{"data-id":"id_2002966"},"menu":{"hasChildren":false},"tocID":"id_2002966-d46e298995","topics":[]},{"title":"Removing the Digitized Per Pin Remote Receiver (DPP RRx)","shortdesc":"<p class=\"shortdesc\">Remove the Digitized Per Pin Remote Receiver (DPP RRx) from the magnet outer electronics.<\/p>","href":"t_RemovingTheDigitizedPerPinRemoteReceiverDPPRRx.html","attributes":{"data-id":"id_2014241"},"menu":{"hasChildren":false},"tocID":"id_2014241-d46e299099","topics":[]},{"title":"Installing the Digitized Per Pin Remote Receiver (DPP RRx)","shortdesc":"<p class=\"shortdesc\">Install a Digitized Per Pin Remote Receiver (DPP RRx) in the magnet outer electronics.<\/p>","href":"t_InstallingTheDigitizedPerPinRemoteReceiverDPPRRx.html","attributes":{"data-id":"id_2014242"},"menu":{"hasChildren":false},"tocID":"id_2014242-d46e299203","topics":[]},{"title":"Installing the magnet rear service access panel","shortdesc":"<p class=\"shortdesc\">Installs the rear service access panel onto the magnet enclosure. This panel covers the components mounted on the left-hand side of the magnet.<\/p>","href":"t_InstallingTheRearServiceAccessPanel_23.html","attributes":{"data-id":"id_2002967"},"menu":{"hasChildren":false},"tocID":"id_2002967-d46e299308","topics":[]},{"title":"Installing the magnet front service access panel","shortdesc":"<p class=\"shortdesc\">Installs the front service access panel onto the magnet enclosure. This panel covers the components mounted on the left-hand side of the magnet.<\/p>","href":"t_InstallingTheFrontServiceAccessPanel_25.html","attributes":{"data-id":"id_2002825"},"menu":{"hasChildren":false},"tocID":"id_2002825-d46e299412","topics":[]},{"title":"Installing the magnet service access trim","shortdesc":"<p class=\"shortdesc\">Installs the service access trim. The trim panel covers the screws securing the front and rear service access panels.<\/p>","href":"t_InstallingTheServiceAccessTrim_27.html","attributes":{"data-id":"id_2002822"},"menu":{"hasChildren":false},"tocID":"id_2002822-d46e299516","topics":[]},{"title":"Removing LOTO - ISC","shortdesc":"<p class=\"shortdesc\">Remove LOTO from the gradient and system PDU breakers on the MDP before restoring power to the ISC.<\/p>","href":"t_Removing-LOTO-ISC_77.html","attributes":{"data-id":"id_2001783"},"menu":{"hasChildren":false},"tocID":"id_2001783-d46e299620","topics":[]},{"title":"Starting up the host computer","shortdesc":"<p class=\"shortdesc\">How to start the host computer.<\/p>","href":"t_StartingUpTheHostComputer_83.html","attributes":{"data-id":"id_2001468"},"menu":{"hasChildren":false},"tocID":"id_2001468-d46e299726","topics":[]},{"title":"Calibrating for quadrature","href":"t_CalibratingForQuadrature_14.html","attributes":{"data-id":"id_2001634"},"menu":{"hasChildren":false},"tocID":"id_2001634-d46e299832","topics":[]},{"title":"Doing a check scan","shortdesc":"<p class=\"shortdesc\"> A check scan is done at the conclusion of many procedures. This functional check assures the unit is in good clinical working order.<\/p>","href":"t_DoingACheckScan_106.html","attributes":{"data-id":"id_2001754"},"menu":{"hasChildren":false},"tocID":"id_2001754-d46e300042","topics":[]}]});